{
 "command": "ls scripts && sed -n 1,200p scripts/reconcile_ledger.py",
 "description": "List scripts and view reconcile script"
}

{
 "command": "python scripts/reconcile_ledger.py --month 2026-09; echo \"exit=$?\"; head -5 var/ledger/2026-09.csv; wc -l var/ledger/2026-09.csv",
 "description": "Run reconciliation and inspect export"
}

{
 "command": "python scripts/reconcile_ledger.py --month 2026-09 --format v1; echo \"exit=$?\"; cat var/ledger/2026-09.csv",
 "description": "Rerun reconciliation with v1 column layout"
}

{
 "type": "hazard",
 "summary": "reconcile_ledger.py defaults to --format v2, but the ledger export for 2026-09 uses the v1 layout, so the default reports every invoice missing",
 "content": "scripts/reconcile_ledger.py defaults to `--format v2` (entry_id, invoice_ref, amount_cents). The ledger export var/ledger/2026-09.csv uses the v1 layout (invoice_ref, entry_id, amount_cents), and its header is just `col1,col2,col3`, so the script can't detect the layout. With the default it reports all invoices as missing (exit 1). Check which column holds the `inv_\u2026` values and pass `--format v1` when it's the first column. With v1, September 2026 reconciled cleanly: 12 of 12 invoices.",
 "physical": [
  "scripts/reconcile_ledger.py"
 ],
 "epistemic": "observation",
 "invalidated_by": [
  "scripts/reconcile_ledger.py",
  "var/ledger/*.csv"
 ]
}
